brute_force_code:
def longest_consecutive(nums):
    if not nums:
        return 0
    best = 1
    uniq = list(set(nums))
    for x in uniq:
        length = 1
        y = x + 1
        while y in uniq:
            length += 1
            y += 1
        best = max(best, length)
    return best

reference_solution:
def longest_consecutive(nums):
    values = set(nums)
    best = 0
    for x in values:
        if x - 1 in values:
            continue
        length = 1
        y = x + 1
        while y in values:
            length += 1
            y += 1
        best = max(best, length)
    return best
